  impact text,
  data jsonb not null default '{}',
  amount numeric(14,2),
  student_id uuid,
  status text not null default 'pending' check (status in ('pending','approved','rejected','returned','cancelled')),
  current_seq integer not null default 1,
  pending_approver_ids uuid[] not null default '{}',
  step_due_at timestamptz,
  linked_type text,
  linked_id uuid,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  foreign key (org_id, approval_type_id) references core.approval_types(org_id, id),
  foreign key (org_id, flow_id) references core.approval_flows(org_id, id),
  foreign key (org_id, applicant_staff_id) references core.staff(org_id, id),
  foreign key (org_id, student_id) references core.students(org_id, id)
);
create index approval_requests_branch on core.approval_requests(org_id, branch_id);
create index approval_requests_approval_type_id on core.approval_requests(org_id, approval_type_id);
create index approval_requests_flow_id on core.approval_requests(org_id, flow_id);
create index approval_requests_applicant_staff_id on core.approval_requests(org_id, applicant_staff_id);
create index approval_requests_student_id on core.approval_requests(org_id, student_id);
create index approval_requests_status on core.approval_requests(org_id, status, step_due_at);
create index approval_requests_linked on core.approval_requests(org_id, linked_type, linked_id);
